update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p126","body":"آج شب تنہائی ہے اور میں\nمسیحائی فقط رسوائی ہے اور میں\nنہ دور دور تک راستہ ہے\nنہ سفر کی آرزو ہے\nنہ دل دھڑکتا ہے\nنہ کوئی جستجو ہے\nنہ خواب آشنا ہیں\nنہ حسرت باقی ہے\nکوئی ادھوری آس تھی\nجو دفن ہو چکی ہے\nکسی کی رمز اب\nفن ہو چکی ہیں\nآج شب تنہائی ہے اور میں\nنہ غم دہائی ہے\nشاید یاد آئی ہے\nیہ آہٹ ! دریچے پہ ، اس پہر\nکسی آشنا کی لگ رہی ہے\nآج شب ! سنا ہے چاندنی پگل رہی ہے\nآنگن میں اجنبی محبت ٹہل رہی ہے"},{"slug":"tum-p127","body":"وہ لوگ جو ہم سے بچھڑ گئے ان کا مبادلہ کون کرے\nوہ خواب جو ہم تھے بھول گئے ان کو سچا کون کرے\n\nوہ راہروؤں کی تبسم فزائیاں ، وہ ہمراہوں کی کڑی تلخیاں\nجنھیں نظر نہ آئے قریب سے ، انھیں دور سے اشارہ کون کرے\n\nایک پیڑ تھا گھر میں نیم کا ،  ٹھیک دریچے کے پاس میں\nوہ درخت ہی جبکہ گر گیا ، پھر صحن پہ سایہ کون کرے\n\nہم چھوڑ آئے اپنی شناخت کو ، ایک تنگ سی کسی گلی میں\nجس گلی کا رستہ بھول گئے ، اس گلی میں جایا کون کرے\n\nکہیں ساحلوں کی تلاش ہے ، کہیں پہنچ کے بھی دل اداس ہے\nاحمد ؔ  کوئے امتحاں ہے ہر کوئی ، اس پہ آہ و بکا کون کرے"},{"slug":"tum-p128","body":"فیصلہ ترک تعلق اگرچہ آسان نہیں تھا\nمگر یہ ابھی اصل امتحان نہیں تھا\n\nتیرے بغیر دل نے خوب ہجرتیں کیں\nتیرے بعد اپنا کوئی مکان نہیں تھا"},{"slug":"tum-p129","body":"کوئی سوچ کا ساماں ہو جیسے\nگل نہ ہو گلستاں ہو جیسے\n\nہر موڑ پہ رک جاتا ہوں\nمنزل بہت آساں ہو جیسے\n\nاس کی جیب میں رہتی ہے حُسن پری\nعشق زیرِ احساں ہو جیسے\n\nشاید کبھی تجھے ایسے بھولوں میں\nتو ہمیشہ سے انجاں ہو جیسے\n\nگزار رہا ہوں ہر پل اس طرح سے\nزندگی کارِ نالاں ہو جیسے\n\nجھانک رہے ہیں سبھی گریباں میں\nیہاں ہر شخص ہی نگراں ہو جیسے\n\nکئی دنوں سے تمہیں دیکھا نہیں\nکئی دن ہی رائیگاں ہو جیسے\nدیکھ رہا ہوں آسمان کو اس طرح\nاحمد ؔ  تو صاف نمایاں ہو جیسے"},{"slug":"tum-p130","body":"وہی دن ہیں\nوہی ہیں راتیں\nوہی روٹھے سے ہم ہیں\nوہی ہیں شامیں\nسب کچھ وہی ہے\nپر کچھ سہی نہیں\nسب ہیں میسر\nبس تم کہیں نہیں\nبالکل اسی طرح\nبادل گرجتے ہیں\nبالکل اسی طرح\nاشک برستے ہیں\nخاموش سحر آتی ہے\nغم کی لہر ستاتی ہے\nدل کی شاخ سوکھ جاتی ہے\nجب جب تمہاری یاد آتی ہے\n\nیادوں کے شہر میں چلے چلتے ہیں\nتم بن ہم یہی کرتے ہیں\nدل کی دہلیز پہ مدہم مدہم\nقدم کچھ سوال رکھتے ہیں\n\nجوابوں کی آڑھ میں گم سم گم سم\nکچھ اشکال ابھرتے ہیں\nکہ جانے کب تک دل جلاو گی\nجانے کب تک یاد آو گی\nآنکھ مری پرنم ہے\nکیوں آخر تو برہم ہے\n\nمزاج ہے اداس اداس\nتری آواز کی سرگم ہے\nعالم ہے سائیں سائیں\nکیسا یہ  انداز تکلم ہے\n\nکون سے غم آخر ستاتے ہیں\nکیوں آکر چھت پہ لیٹ جاتے ہیں\nستارے جگمگاتے ہیں\nبس یہ کہتے جاتے ہیں\nکیا یہ کم ہے\nبس تیرا غم ہے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
